use super::*;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
use crate::{io::BoundedIo,resources::ResourceBudget};
use std::os::unix::fs::PermissionsExt;
struct Adapter {
    journal:PathBuf,shown:Mutex<Vec<NotificationMessage>>,permission:Mutex<NotificationPermission>,requests:Mutex<Vec<bool>>,
    outcome:Mutex<NativeDelivery>,block:AtomicBool,entered:tokio::sync::Notify,pending_remove:AtomicBool,removed:AtomicUsize,
}
impl NotificationAdapter for Adapter {
    fn permission<'a>(&'a self,request:bool,cancel:&'a CancellationToken)->BoxFuture<'a,Result<NotificationPermission>>{Box::pin(async move{check_cancel(cancel)?;self.requests.lock().unwrap().push(request);Ok(*self.permission.lock().unwrap())})}
    fn submit<'a>(&'a self,message:NotificationMessage,cancel:&'a CancellationToken)->BoxFuture<'a,Result<NativeDelivery>>{Box::pin(async move{
        let journal:Journal=serde_json::from_slice(&std::fs::read(&self.journal).unwrap()).unwrap();assert!(journal.cursor.unconfirmed,"claim must be persisted before native submission");
        self.shown.lock().unwrap().push(message);self.entered.notify_one();if self.block.load(Ordering::SeqCst){cancel.cancelled().await;return Err(Error::cancelled());}check_cancel(cancel)?;Ok(*self.outcome.lock().unwrap())
    })}
    fn settle<'a>(&'a self,_id:&'a str,cancel:&'a CancellationToken)->BoxFuture<'a,Result<NativeDelivery>>{Box::pin(async move{check_cancel(cancel)?;Ok(*self.outcome.lock().unwrap())})}
    fn remove<'a>(&'a self,_id:&'a str)->BoxFuture<'a,Result<NativeRemoval>>{Box::pin(async move{self.removed.fetch_add(1,Ordering::SeqCst);Ok(if self.pending_remove.load(Ordering::SeqCst){NativeRemoval::Pending}else{NativeRemoval::Confirmed})})}
    fn drain(&self)->BoxFuture<'_,Result<NativeDrain>>{Box::pin(async move{Ok(if self.pending_remove.load(Ordering::SeqCst){NativeDrain::Pending}else{NativeDrain::Complete})})}
}
struct Fixture {dir:tempfile::TempDir,io:BoundedIo,worker:DataWorker,prefs:Arc<Mutex<NotificationSettings>>,adapter:Arc<Adapter>,changes:Arc<Mutex<Vec<NotificationState>>>}
impl Fixture {
    fn new()->Self {
        let executable=std::env::var_os("OC_DATA_WORKER_TEST_EXECUTABLE").expect("build oc-data-worker and set OC_DATA_WORKER_TEST_EXECUTABLE to its absolute executable path");
        let dir=tempfile::Builder::new().permissions(std::fs::Permissions::from_mode(0o700)).tempdir().unwrap();let io=BoundedIo::new(ResourceBudget::default());let worker=DataWorker::new(io.clone(),PathBuf::from(executable));
        let prefs=Arc::new(Mutex::new(NotificationSettings{enabled:true,source_ids:vec!["hermes-events".into()],..NotificationSettings::default()}));
        let adapter=Arc::new(Adapter{journal:dir.path().join("notifications.json"),shown:Mutex::new(vec![]),permission:Mutex::new(NotificationPermission::Authorized),requests:Mutex::new(vec![]),outcome:Mutex::new(NativeDelivery::Displayed),block:AtomicBool::new(false),entered:tokio::sync::Notify::new(),pending_remove:AtomicBool::new(false),removed:AtomicUsize::new(0)});
        Self{dir,io,worker,prefs,adapter,changes:Arc::new(Mutex::new(vec![]))}
    }
    fn service(&self)->Arc<EventNotifications>{let prefs=self.prefs.clone();let changes=self.changes.clone();Arc::new(EventNotifications::new(NotificationOptions{journal:self.adapter.journal.clone(),worker:self.worker.clone(),preferences:Arc::new(move||prefs.lock().unwrap().clone()),language:Arc::new(||ResolvedLanguage::English),adapter:self.adapter.clone(),task_name:Arc::new(|_|Some("private task name 中文".into())),changed:Arc::new(move|state|changes.lock().unwrap().push(state))}))}
    fn journal(&self)->Journal{serde_json::from_slice(&std::fs::read(&self.adapter.journal).unwrap()).unwrap()}
    fn shown(&self)->usize{self.adapter.shown.lock().unwrap().len()}
}
fn batch(start:u64,count:u64)->NotificationBatch{let now=Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true);NotificationBatch{identity:"database:one".into(),events:(start..start+count).map(|i|(i,LocalEvent{id:format!("event-{i}"),source_id:"hermes-events".into(),entity_id:format!("task-{i}"),event_type:LocalEventType::ExecutionFailed,occurred_at:None,observed_at:now.clone(),result_code:"failed".into(),target:Some(NavigationTarget::Schedule{id:format!("hermes-job:{i}"),identity:"metadata".into()})})).collect()}}
#[tokio::test]async fn notifications_disabled_never_opens_journal_or_native(){let f=Fixture::new();f.prefs.lock().unwrap().enabled=false;let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(1,1)).await.unwrap();n.stop().await.unwrap();assert!(!f.adapter.journal.exists());assert!(f.adapter.requests.lock().unwrap().is_empty());assert_eq!(f.shown(),0);f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_claim_precedes_submit_and_duplicate_is_not_replayed(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(1,3)).await.unwrap();assert_eq!(f.shown(),3);assert!(!f.journal().cursor.unconfirmed);n.committed(batch(1,3)).await.unwrap();assert_eq!(f.shown(),3);assert!(f.adapter.shown.lock().unwrap().iter().all(|m|!m.body.contains("private task name")));n.stop().await.unwrap();assert_eq!(f.adapter.removed.load(Ordering::SeqCst),3);f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_rate_limit_summary_and_backwards_clock(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();let now=Utc::now();n.consume(batch(1,100),now).await.unwrap();assert_eq!(f.shown(),3);assert_eq!(f.journal().summary_count,97);n.consume(batch(101,0),now+chrono::Duration::seconds(30)).await.unwrap();assert_eq!(f.shown(),3);n.consume(batch(101,0),now+chrono::Duration::seconds(70)).await.unwrap();assert_eq!(f.shown(),4);assert_eq!(f.journal().summary_count,0);assert!(f.adapter.shown.lock().unwrap()[3].body.contains("97"));n.consume(batch(101,100),now+chrono::Duration::seconds(10)).await.unwrap();assert!(f.journal().sent_at.len()<=3);assert!(f.shown()<=6);n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_unknown_delivery_retains_claim_across_restart(){let f=Fixture::new();*f.adapter.outcome.lock().unwrap()=NativeDelivery::Pending;let first=f.service();first.start(&CancellationToken::new()).await.unwrap();assert!(first.committed(batch(1,2)).await.is_err());assert_eq!(first.snapshot().last_outcome,Some(NotificationOutcome::Unconfirmed));assert!(f.journal().cursor.unconfirmed);assert_eq!(f.journal().cursor.sequence,2);first.stop().await.unwrap();let restarted=f.service();restarted.start(&CancellationToken::new()).await.unwrap();assert_eq!(restarted.snapshot().last_outcome,Some(NotificationOutcome::Unconfirmed));*f.adapter.outcome.lock().unwrap()=NativeDelivery::Displayed;restarted.committed(batch(1,2)).await.unwrap();assert_eq!(f.shown(),1);restarted.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_failed_claim_prevents_submission(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();std::fs::create_dir(&f.adapter.journal).unwrap();assert!(n.committed(batch(1,1)).await.is_err());assert_eq!(f.shown(),0);assert_eq!(n.snapshot().phase,NotificationPhase::Error);assert!(n.stop().await.unwrap_err().is_cleanup());std::fs::remove_dir(&f.adapter.journal).unwrap();n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_sleep_cancels_current_show_and_summarizes_only_unattempted(){let f=Fixture::new();f.adapter.block.store(true,Ordering::SeqCst);let n=f.service();n.start(&CancellationToken::new()).await.unwrap();let task={let n=n.clone();tokio::spawn(async move{n.committed(batch(1,3)).await})};f.adapter.entered.notified().await;n.sleep().await.unwrap();assert!(task.await.unwrap().unwrap_err().is_cancelled());assert_eq!(f.shown(),1);assert_eq!(f.journal().summary_count,2);assert!(f.journal().cursor.unconfirmed);f.adapter.block.store(false,Ordering::SeqCst);n.wake().await.unwrap();n.committed(batch(4,0)).await.unwrap();assert_eq!(f.shown(),2);assert!(f.adapter.shown.lock().unwrap()[1].body.contains('2'));n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_pending_removal_blocks_stop_until_confirmed(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(1,1)).await.unwrap();f.adapter.pending_remove.store(true,Ordering::SeqCst);let error=n.stop().await.unwrap_err();assert!(error.is_cleanup());assert_eq!(n.snapshot().phase,NotificationPhase::Error);assert!(!n.state.lock().unwrap().handles.is_empty());f.adapter.pending_remove.store(false,Ordering::SeqCst);n.stop().await.unwrap();assert!(n.state.lock().unwrap().handles.is_empty());f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_disable_cancels_and_drains_without_replaying_on_enable(){let f=Fixture::new();let n=f.service();let parent=CancellationToken::new();n.start(&parent).await.unwrap();f.adapter.block.store(true,Ordering::SeqCst);let task={let n=n.clone();tokio::spawn(async move{n.committed(batch(1,3)).await})};f.adapter.entered.notified().await;f.prefs.lock().unwrap().enabled=false;n.refresh(&parent).await.unwrap();assert!(task.await.unwrap().is_err());assert_eq!(f.journal().summary_count,0);assert_eq!(n.snapshot().phase,NotificationPhase::Off);f.prefs.lock().unwrap().enabled=true;f.adapter.block.store(false,Ordering::SeqCst);n.refresh(&parent).await.unwrap();n.committed(batch(1,3)).await.unwrap();assert_eq!(f.shown(),1);n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_permissions_are_explicit_and_names_opt_in(){let f=Fixture::new();*f.adapter.permission.lock().unwrap()=NotificationPermission::Denied;let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(1,1)).await.unwrap();assert_eq!(f.shown(),0);assert_eq!(*f.adapter.requests.lock().unwrap(),vec![false]);*f.adapter.permission.lock().unwrap()=NotificationPermission::Authorized;n.request_permission().await.unwrap();assert_eq!(*f.adapter.requests.lock().unwrap(),vec![false,true]);f.prefs.lock().unwrap().show_task_names=true;n.committed(batch(2,1)).await.unwrap();assert!(f.adapter.shown.lock().unwrap().iter().any(|m|m.body.contains("private task name")));n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_database_change_resets_cursor_but_preserves_rate(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(100,3)).await.unwrap();let mut changed=batch(1,1);changed.identity="database:two".into();n.committed(changed).await.unwrap();assert_eq!(f.shown(),3);assert_eq!(f.journal().identity.as_deref(),Some("database:two"));assert_eq!(f.journal().cursor.sequence,1);assert_eq!(f.journal().summary_count,1);n.stop().await.unwrap();f.io.shutdown().await.unwrap();}
#[tokio::test]async fn notifications_summary_overflow_keeps_previous_cursor(){let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.set_sleeping(true);{let mut state=n.state.lock().unwrap();let journal=state.journal.as_mut().unwrap();journal.identity=Some("database:one".into());journal.summary_count=SAFE_INTEGER;}let error=n.committed(batch(1,1)).await.unwrap_err();assert_eq!(error.code,"OC_NOTIFICATION_SUMMARY_LIMIT");assert_eq!(n.state.lock().unwrap().journal.as_ref().unwrap().cursor.sequence,0);assert_eq!(f.shown(),0);n.stop().await.unwrap();f.io.shutdown().await.unwrap();}

#[tokio::test]async fn notifications_cleanup_reloads_claim_after_lost_commit_acknowledgement(){
    let f=Fixture::new();let n=f.service();n.start(&CancellationToken::new()).await.unwrap();
    let journal=Journal{identity:Some("database:one".into()),cursor:Cursor{sequence:55,unconfirmed:true},summary_count:7,..Journal::default()};
    n.save(&journal,&CancellationToken::new()).await.unwrap();
    // The durable rename happened but its reply was lost. In-memory state is
    // deliberately older, exactly the state that must never overwrite a claim.
    {let mut state=n.state.lock().unwrap();state.journal=None;state.journal_uncertain=true;state.blocked=true;}
    n.stop().await.unwrap();let persisted=f.journal();assert_eq!(persisted.cursor.sequence,55);assert!(persisted.cursor.unconfirmed);assert_eq!(persisted.summary_count,0);assert_eq!(f.shown(),0);f.io.shutdown().await.unwrap();
}

#[tokio::test]async fn notifications_unsubscribed_recovery_clears_entity_cooldown(){
    let f=Fixture::new();f.prefs.lock().unwrap().event_types=vec![LocalEventType::ExecutionFailed];let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.committed(batch(1,1)).await.unwrap();
    let mut recovery=batch(2,1);recovery.events[0].1.entity_id="task-1".into();recovery.events[0].1.event_type=LocalEventType::SourceRecovered;n.committed(recovery).await.unwrap();assert!(f.journal().cooldowns.is_empty());assert_eq!(f.shown(),1);
    let mut failure=batch(3,1);failure.events[0].1.entity_id="task-1".into();n.committed(failure).await.unwrap();assert_eq!(f.shown(),2);n.stop().await.unwrap();f.io.shutdown().await.unwrap();
}
#[tokio::test]async fn notifications_quiet_suppression_releases_one_summary(){
    let f=Fixture::new();let now=Utc::now();let minute=local_minute(now);{let mut settings=f.prefs.lock().unwrap();settings.quiet.enabled=true;settings.quiet.start_minute=(minute+1439)%1440;settings.quiet.end_minute=(minute+1)%1440;}
    let n=f.service();n.start(&CancellationToken::new()).await.unwrap();n.consume(batch(1,5),now).await.unwrap();assert_eq!(f.shown(),0);assert_eq!(f.journal().summary_count,5);f.prefs.lock().unwrap().quiet.enabled=false;n.consume(batch(6,0),now).await.unwrap();assert_eq!(f.shown(),1);assert!(f.adapter.shown.lock().unwrap()[0].body.contains('5'));n.stop().await.unwrap();f.io.shutdown().await.unwrap();
}
#[test]fn notifications_subscription_bounds_are_rejected(){
    let mut settings=NotificationSettings::default();settings.source_ids=(0..65).map(|i|format!("source-{i}")).collect();assert!(settings.validate().is_err());settings.source_ids.truncate(64);assert!(settings.validate().is_ok());settings.tasks=(0..25).map(|i|NavigationTarget::Schedule{id:format!("hermes-job:{i}"),identity:"metadata".into()}).collect();assert!(settings.validate().is_err());settings.tasks.truncate(24);assert!(settings.validate().is_ok());
}
